mapper.select:
SELECT id, order_id, menu_item_id, name, unit, price, qty, amount FROM order_items WHERE order_id IN
#{orderId}
ORDER BY id

SELECT oi.name AS name, oi.unit AS unit, SUM(oi.qty) AS totalQty, SUM(oi.amount) AS totalAmount FROM order_items oi JOIN orders o ON oi.order_id = o.id WHERE o.status = 'VALID' AND o.meal_date BETWEEN #{start} AND #{end}
AND o.user_id = #{userId}
GROUP BY oi.name, oi.unit ORDER BY totalAmount DESC
